/* CurveScout public folder for Cloudflare (r70).  node .github/scripts/cf-public.mjs <out-dir> [--check-only] [--preview]
   Builds the folder that Cloudflare publishes from the repository: everything a visitor needs, nothing else.
   Left out (never published): repository metadata, workflows and scripts, the Cloudflare sources, ops logs,
   upload zips, source maps, environment files. Then it checks the result against Cloudflare's limits and stops the
   deploy (exit 1) when anything is wrong. Files are hard-linked, so a 840 MB site costs no extra disk.
   Also writes _redirects: one exact rule pair per folder page (/x -> /x/ and /x/ -> /x/index.html), because the
   Worker serves files with html_handling "none" so that every .html address stays exactly as it is today. */
import fs from 'node:fs'; import path from 'node:path';
export const LIMITS = { files: 100000, filesWarn: 80000, bytes: 25 * 1048576, bytesWarn: 20 * 1048576, redirects: 2000 };
const SKIP_TOP = new Set(['.git', '.github', 'cloudflare', 'ops', 'inbox', 'tools', 'node_modules', '_public', 'README.md', 'LICENSE', 'CNAME', '.nojekyll', 'wrangler.jsonc', 'wrangler.toml', '.dev.vars', 'sitemap-state.json.gz']);
/* build-only data: read by the release and sitemap scripts, never by a page (checked r70) - private on Cloudflare */
const SKIP_PATH = new Set(['data/index/release-plan.json', 'data/index/release-log.json', 'data/index/site-counts.json']);
const SKIP_ANY = [/\.map$/i, /(^|\/)\.env/i, /(^|\/)\.DS_Store$/, /\.zip$/i, /(^|\/)Thumbs\.db$/i];
const SECRET = [/ghp_[A-Za-z0-9]{30,}/, /github_pat_[A-Za-z0-9_]{40,}/, /AKIA[0-9A-Z]{16}/, /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /\bsk_live_[A-Za-z0-9]{20,}/, /xox[bp]-[A-Za-z0-9-]{20,}/];
const MAPREF = /[#@]\s*sourceMappingURL=/;
export function build(root, out, { link = true, preview = false } = {}) {
  const r = { files: 0, bytes: 0, largest: [], blocks: [], warns: [], folders: [] };
  fs.rmSync(out, { recursive: true, force: true }); fs.mkdirSync(out, { recursive: true });
  const walk = rel => {
    for (const d of fs.readdirSync(path.join(root, rel), { withFileTypes: true })) {
      const p = rel ? rel + '/' + d.name : d.name;
      if (!rel && SKIP_TOP.has(d.name)) continue;
      if (SKIP_PATH.has(p)) continue;
      if (SKIP_ANY.some(x => x.test(p))) continue;
      if (d.isDirectory()) { fs.mkdirSync(path.join(out, p), { recursive: true }); walk(p); continue; }
      if (!d.isFile()) continue;
      const src = path.join(root, p), st = fs.statSync(src);
      if (link) { try { fs.linkSync(src, path.join(out, p)); } catch (e) { fs.copyFileSync(src, path.join(out, p)); } } else fs.copyFileSync(src, path.join(out, p));
      r.files++; r.bytes += st.size; r.largest.push([st.size, p]);
      if (d.name === 'index.html' && rel) r.folders.push(rel);
      if (st.size > LIMITS.bytes) r.blocks.push('file over 25 MiB: ' + p); else if (st.size > LIMITS.bytesWarn) r.warns.push('file over 20 MiB: ' + p);
      if (/\.(js|mjs|html?|json|txt|css|xml|webmanifest)$/i.test(p) && st.size < 30e6) {
        const t = fs.readFileSync(src, 'utf8');
        if (MAPREF.test(t)) r.blocks.push('source map reference: ' + p);
        for (const s of SECRET) if (s.test(t)) r.blocks.push('looks like a secret: ' + p);
      }
    }
  };
  walk('');
  for (const need of ['index.html', 'app.js', 'sw.js', '404.html', 'robots.txt', 'sitemap.xml', 'ads.txt']) if (!fs.existsSync(path.join(out, need))) r.blocks.push('missing ' + need);
  /* Cloudflare-only files */
  const cf = path.join(root, 'cloudflare');
  if (fs.existsSync(path.join(cf, '_headers'))) {
    let h = fs.readFileSync(path.join(cf, '_headers'), 'utf8');
    if (preview) h += '\n# PREVIEW BUILD: never indexed\n/*\n  X-Robots-Tag: noindex, nofollow\n';
    fs.writeFileSync(path.join(out, '_headers'), h); r.files++; }
  const rules = ['/  /index.html  200'];
  for (const f of r.folders.sort()) rules.push(`/${f}  /${f}/  301`, `/${f}/  /${f}/index.html  200`);
  if (rules.length > LIMITS.redirects) r.blocks.push(`${rules.length} redirect rules (limit ${LIMITS.redirects})`);
  fs.writeFileSync(path.join(out, '_redirects'), '# CurveScout folder pages (generated by cf-public.mjs)\n' + rules.join('\n') + '\n'); r.files++;
  r.rules = rules.length;
  if (r.files > LIMITS.files) r.blocks.push(`${r.files} files (Cloudflare limit ${LIMITS.files} per version)`); else if (r.files > LIMITS.filesWarn) r.warns.push(`${r.files} files (early warning at ${LIMITS.filesWarn})`);
  r.largest = r.largest.sort((a, b) => b[0] - a[0]).slice(0, 3);
  return r;
}
if (process.argv[1] && process.argv[1].endsWith('cf-public.mjs')) {
  const out = process.argv[2] || '_public', check = process.argv.includes('--check-only'), preview = process.argv.includes('--preview');
  const r = build('.', out, { preview });
  console.log(`Public folder: ${r.files} files, ${(r.bytes / 1048576).toFixed(0)} MiB, ${r.rules} folder rules; largest ${r.largest.map(([b, f]) => f + ' ' + (b / 1048576).toFixed(1) + ' MiB').join(', ')}`);
  for (const w of r.warns) console.log('WARN  ' + w);
  for (const b of r.blocks.slice(0, 40)) console.log('BLOCK ' + b);
  if (check) fs.rmSync(out, { recursive: true, force: true });
  process.exit(r.blocks.length ? 1 : 0);
}
